-- Castle Nathria elevators: GO 327444, 5 spawns on map 2296.
-- Frames are real: TransportAnimation.db2 rows 377934-378279, identical in 9.2.7 client data and in
-- retail 12.1.5.70688. Renumbered to 179986-180331, continuing TransportAnimation.dbc.
-- This table is the overlay the server merges over its binary DBC at boot. The client cannot see it,
-- so the same rows also go into TransportAnimation.dbc on the client side.
DELETE FROM `transportanimation_dbc` WHERE `TransportID` = 327444;

-- state 24 is the retail transport-active value. ObjectMgr skips any state of 3 or more, and
-- StaticTransport::Create ignores the column after that, so 1 only has to pass that check. Stock elevators hold 1.
UPDATE `gameobject` SET `state` = 1 WHERE `guid` IN (15100012, 15100074, 15100076, 15100215, 15100216) AND `id` = 327444 AND `state` = 24;
